H.background();
const cx = H.W * 0.42, cy = H.H * 0.62;
const A = P.A; // interior angle at vertex B (degrees), slider
const Bx = cx - 200, By = cy;
const Cx = cx + 200, Cy = cy;
const angB = A * Math.PI / 180;
const angCdeg = 55; // fixed interior angle at C (adjacent to the exterior angle)
const angC = angCdeg * Math.PI / 180;
const denom = Math.sin(angB + angC);
const safe = Math.abs(denom) < 1e-4 ? 1e-4 : denom;
const BC = (Cx - Bx);
const dist = BC * Math.sin(angC) / safe; // length B->apex
const Ax = Bx + dist * Math.cos(angB);
const Ay = By - dist * Math.sin(angB);
const angAdeg = 180 - A - angCdeg; // remote interior angle at apex
const extDeg = angAdeg + A; // exterior at C = sum of remote interiors (apex + B) = 180 - 55 = 125
// draw triangle
H.path([[Bx,By],[Cx,Cy],[Ax,Ay]], { color: H.colors.accent, width: 3, close: true });
// extend base beyond C to show exterior angle
const Ex = Cx + 160;
H.line(Bx, By, Ex, By, { color: H.colors.grid, width: 2, dash: [6,5] });
H.line(Cx, Cy, Ex, By, { color: H.colors.grid, width: 1 });
// exterior angle at C is between CA and the extension CE (toward +x)
const baseAng = 0; // extension direction
const caAng = Math.atan2(Ay - Cy, Ax - Cx); // direction C->A
